(1, 2, '_wp_page_template', 'default'),
(2, 3, '_wp_page_template', 'default'),
(13, 3, '_wp_trash_meta_status', 'draft'),
(14, 3, '_wp_trash_meta_time', '1786102600'),
(15, 3, '_wp_desired_post_slug', 'privacy-policy'),
(16, 2, '_wp_trash_meta_status', 'publish'),
(17, 2, '_wp_trash_meta_time', '1786102602'),
(18, 2, '_wp_desired_post_slug', 'sample-page'),
(19, 14, '_edit_lock', '1786110232:1'),
(20, 14, '_wp_page_template', 'page-templates/template-home.php'),
(21, 14, '_edit_last', '1'),
(22, 14, 'hero_image', '21'),
(23, 14, '_hero_image', 'field_home_hero_image'),
(24, 14, 'hero_title', 'Open a College. Partner With a Name People Already Trust.'),
(25, 14, '_hero_title', 'field_home_hero_title'),
(26, 14, 'hero_text', 'United Group of Colleges (UGC) enables visionaries, landowners and educational leaders to establish and operate a high-impact college in South Punjab under an established academic brand, without building an institution from scratch. We help you transform your existing campus into a modern, fully managed institution: you supply the property and capital, while we provide the brand, digital management systems, operational playbooks, staff training and continuous academic oversight. '),
(27, 14, '_hero_text', 'field_home_hero_text'),
(28, 14, 'hero_button_1_text', 'Request Franchise Information'),
(29, 14, '_hero_button_1_text', 'field_home_hero_btn1_text'),
(30, 14, 'hero_button_1_url', ''),
(31, 14, '_hero_button_1_url', 'field_home_hero_btn1_url'),
(32, 14, 'hero_button_2_text', 'See How It Works'),
(33, 14, '_hero_button_2_text', 'field_home_hero_btn2_text'),
(34, 14, 'hero_button_2_url', ''),
(35, 14, '_hero_button_2_url', 'field_home_hero_btn2_url'),
(36, 14, 'simpler_way_heading', 'A Simpler Way into the <span class=\"text-accent\">Education System</span>'),
(37, 14, '_simpler_way_heading', 'field_home_simpler_heading'),
(38, 14, 'simpler_way_text', 'Starting a college on your own, involves navigating regulatory friction, designing curriculum architectures, setting up IT systems and spending years building public trust. UGC delivers a ready-made education system so you can skip years of trial and error and open with credibility from day one.'),
(39, 14, '_simpler_way_text', 'field_home_simpler_text'),
(40, 14, 'regional_heading', 'Pathways for <span class=\"text-accent\">Regional Investors</span>'),
(41, 14, '_regional_heading', 'field_home_regional_heading'),
(42, 14, 'timeline_heading', 'How the UGC Franchise Works'),
(43, 14, '_timeline_heading', 'field_home_timeline_heading'),
(44, 14, 'models_heading', 'Campus Models Tailored to <span class=\"text-accent\">Your Market</span>'),
(45, 14, '_models_heading', 'field_home_models_heading'),
(46, 14, 'models_intro', 'Choose the campus model that fits your budget, real estate assets and local demand:'),
(47, 14, '_models_intro', 'field_home_models_intro'),
(48, 14, 'models_footnote', 'All program offerings across all models are proposed and subject to final regulatory and government approvals.'),
(49, 14, '_models_footnote', 'field_home_models_footnote'),
(50, 14, 'why_image', '94'),
(51, 14, '_why_image', 'field_home_why_image'),
(52, 14, 'why_badge_title', 'Regional Focus'),
(53, 14, '_why_badge_title', 'field_home_why_badge_title'),
(54, 14, 'why_badge_text', 'Multan, Bahawalpur, and Dera Ghazi Khan divisions.'),
(55, 14, '_why_badge_text', 'field_home_why_badge_text'),
(56, 14, 'why_heading', 'Why South Punjab, <span class=\"text-accent\">Why Now?</span>'),
(57, 14, '_why_heading', 'field_home_why_heading'),
(58, 14, 'why_text_1', 'Families across Multan, Bahawalpur and Dera Ghazi Khan divisions, want quality college education close to home and are willing to pay for it. Yet many towns still lack a trusted name to turn to. A UGC campus meets that demand, earns tuition income over time and creates an enduring legacy in your community.\r\n'),
(59, 14, '_why_text_1', 'field_home_why_text_1'),
(60, 14, 'why_text_2', 'Partnering now means joining an established brand while the network is still young and securing your city before someone else does.\r\n'),
(61, 14, '_why_text_2', 'field_home_why_text_2'),
(62, 14, 'why_highlight_title', 'First-Mover Advantage'),
(63, 14, '_why_highlight_title', 'field_home_why_highlight_title'),
