(315, 72, 'hero_title', 'Open a College. Partner With a Name People Already Trust.'),
(316, 72, '_hero_title', 'field_home_hero_title'),
(317, 72, 'hero_text', 'United Group of Colleges (UGC) enables visionaries, landowners and educational leaders to establish and operate a high-impact college in South Punjab under an established academic brand, without building an institution from scratch. We help you transform your existing campus into a modern, fully managed institution: you supply the property and capital, while we provide the brand, digital management systems, operational playbooks, staff training and continuous academic oversight. \r\n'),
(318, 72, '_hero_text', 'field_home_hero_text'),
(319, 72, 'hero_button_1_text', 'Request Franchise Information'),
