(1133, 81, 'footnotes', ''),
(1135, 81, 'hero_image', ''),
(1136, 81, '_hero_image', 'field_home_hero_image'),
(1137, 81, 'hero_title', 'Open a College. Partner With a Name People Already Trust.'),
(1138, 81, '_hero_title', 'field_home_hero_title'),
(1139, 81, 'hero_text', 'United Group of Colleges (UGC) enables visionaries, landowners and educational leaders to establish and operate a high-impact college in South Punjab under an established academic brand, without building an institution from scratch. We help you transform your existing campus into a modern, fully managed institution: you supply the property and capital, while we provide the brand, digital management systems, operational playbooks, staff training and continuous academic oversight. '),
(1140, 81, '_hero_text', 'field_home_hero_text'),
(1141, 81, 'hero_button_1_text', 'Request Franchise Information'),
(1142, 81, '_hero_button_1_text', 'field_home_hero_btn1_text'),
(1143, 81, 'hero_button_1_url', ''),
(1144, 81, '_hero_button_1_url', 'field_home_hero_btn1_url'),
(1145, 81, 'hero_button_2_text', 'See How It Works'),
(1146, 81, '_hero_button_2_text', 'field_home_hero_btn2_text'),
(1147, 81, 'hero_button_2_url', ''),
(1148, 81, '_hero_button_2_url', 'field_home_hero_btn2_url'),
(1149, 81, 'simpler_way_heading', 'A Simpler Way into the <span class=\"text-accent\">Education System</span>'),
(1150, 81, '_simpler_way_heading', 'field_home_simpler_heading'),
(1151, 81, 'simpler_way_text', 'Starting a college on your own, involves navigating regulatory friction, designing curriculum architectures, setting up IT systems and spending years building public trust. UGC delivers a ready-made education system so you can skip years of trial and error and open with credibility from day one.'),
(1152, 81, '_simpler_way_text', 'field_home_simpler_text'),
(1153, 81, 'regional_heading', 'Pathways for <span class=\"text-accent\">Regional Investors</span>'),
(1154, 81, '_regional_heading', 'field_home_regional_heading'),
(1155, 81, 'timeline_heading', 'How the UGC Franchise Works'),
(1156, 81, '_timeline_heading', 'field_home_timeline_heading'),
(1157, 81, 'models_heading', 'Campus Models Tailored to <span class=\"text-accent\">Your Market</span>'),
(1158, 81, '_models_heading', 'field_home_models_heading'),
(1159, 81, 'models_intro', 'Choose the campus model that fits your budget, real estate assets and local demand:'),
(1160, 81, '_models_intro', 'field_home_models_intro'),
(1161, 81, 'models_footnote', 'All program offerings across all models are proposed and subject to final regulatory and government approvals.'),
(1162, 81, '_models_footnote', 'field_home_models_footnote'),
(1163, 81, 'why_image', ''),
(1164, 81, '_why_image', 'field_home_why_image'),
(1165, 81, 'why_badge_title', 'Regional Focus'),
(1166, 81, '_why_badge_title', 'field_home_why_badge_title'),
(1167, 81, 'why_badge_text', 'Multan, Bahawalpur, and Dera Ghazi Khan divisions.'),
(1168, 81, '_why_badge_text', 'field_home_why_badge_text'),
(1169, 81, 'why_heading', 'Why South Punjab, <span class=\"text-accent\">Why Now?</span>'),
(1170, 81, '_why_heading', 'field_home_why_heading'),
(1171, 81, 'why_text_1', 'Families across Multan, Bahawalpur and Dera Ghazi Khan divisions, want quality college education close to home and are willing to pay for it. Yet many towns still lack a trusted name to turn to. A UGC campus meets that demand, earns tuition income over time and creates an enduring legacy in your community.\r\n'),
(1172, 81, '_why_text_1', 'field_home_why_text_1'),
(1173, 81, 'why_text_2', 'Partnering now means joining an established brand while the network is still young and securing your city before someone else does.\r\n'),
(1174, 81, '_why_text_2', 'field_home_why_text_2'),
(1175, 81, 'why_highlight_title', 'First-Mover Advantage'),
(1176, 81, '_why_highlight_title', 'field_home_why_highlight_title'),
(1177, 81, 'why_highlight_text', 'Secure your territory in high-demand regions before the market saturates.'),
