(1757, 89, 'hero_image', '21'),
(1758, 89, '_hero_image', 'field_home_hero_image'),
(1759, 89, 'hero_title', 'Open a College. Partner With a Name People Already Trust.'),
(1760, 89, '_hero_title', 'field_home_hero_title'),
(1761, 89, 'hero_text', 'United Group of Colleges (UGC) enables visionaries, landowners and educational leaders to establish and operate a high-impact college in South Punjab under an established academic brand, without building an institution from scratch. We help you transform your existing campus into a modern, fully managed institution: you supply the property and capital, while we provide the brand, digital management systems, operational playbooks, staff training and continuous academic oversight. '),
(1762, 89, '_hero_text', 'field_home_hero_text'),
