(1771, 89, 'simpler_way_heading', 'A Simpler Way into the <span class=\"text-accent\">Education System</span>'),
(1772, 89, '_simpler_way_heading', 'field_home_simpler_heading'),
(1773, 89, 'simpler_way_text', 'Starting a college on your own, involves navigating regulatory friction, designing curriculum architectures, setting up IT systems and spending years building public trust. UGC delivers a ready-made education system so you can skip years of trial and error and open with credibility from day one.'),
(1774, 89, '_simpler_way_text', 'field_home_simpler_text'),
