(2175, 97, 'footnotes', ''),
(2177, 97, 'hero_image', '21'),
(2178, 97, '_hero_image', 'field_home_hero_image'),
(2179, 97, 'hero_title', 'Open a College. Partner With a Name People Already Trust.'),
(2180, 97, '_hero_title', 'field_home_hero_title'),
(2181, 97, 'hero_text', 'United Group of Colleges (UGC) enables visionaries, landowners and educational leaders to establish and operate a high-impact college in South Punjab under an established academic brand, without building an institution from scratch. We help you transform your existing campus into a modern, fully managed institution: you supply the property and capital, while we provide the brand, digital management systems, operational playbooks, staff training and continuous academic oversight. '),
(2182, 97, '_hero_text', 'field_home_hero_text'),
(2183, 97, 'hero_button_1_text', 'Request Franchise Information'),
(2184, 97, '_hero_button_1_text', 'field_home_hero_btn1_text'),
(2185, 97, 'hero_button_1_url', ''),
(2186, 97, '_hero_button_1_url', 'field_home_hero_btn1_url'),
(2187, 97, 'hero_button_2_text', 'See How It Works'),
(2188, 97, '_hero_button_2_text', 'field_home_hero_btn2_text'),
(2189, 97, 'hero_button_2_url', ''),
(2190, 97, '_hero_button_2_url', 'field_home_hero_btn2_url'),
(2191, 97, 'simpler_way_heading', 'A Simpler Way into the <span class=\"text-accent\">Education System</span>'),
(2192, 97, '_simpler_way_heading', 'field_home_simpler_heading'),
(2193, 97, 'simpler_way_text', 'Starting a college on your own, involves navigating regulatory friction, designing curriculum architectures, setting up IT systems and spending years building public trust. UGC delivers a ready-made education system so you can skip years of trial and error and open with credibility from day one.'),
(2194, 97, '_simpler_way_text', 'field_home_simpler_text'),
(2195, 97, 'regional_heading', 'Pathways for <span class=\"text-accent\">Regional Investors</span>'),
(2196, 97, '_regional_heading', 'field_home_regional_heading'),
(2197, 97, 'timeline_heading', 'How the UGC Franchise Works'),
(2198, 97, '_timeline_heading', 'field_home_timeline_heading'),
(2199, 97, 'models_heading', 'Campus Models Tailored to <span class=\"text-accent\">Your Market</span>'),
(2200, 97, '_models_heading', 'field_home_models_heading'),
(2201, 97, 'models_intro', 'Choose the campus model that fits your budget, real estate assets and local demand:'),
(2202, 97, '_models_intro', 'field_home_models_intro'),
(2203, 97, 'models_footnote', 'All program offerings across all models are proposed and subject to final regulatory and government approvals.'),
(2204, 97, '_models_footnote', 'field_home_models_footnote'),
(2205, 97, 'why_image', '94'),
(2206, 97, '_why_image', 'field_home_why_image'),
(2207, 97, 'why_badge_title', 'Regional Focus'),
(2208, 97, '_why_badge_title', 'field_home_why_badge_title'),
(2209, 97, 'why_badge_text', 'Multan, Bahawalpur, and Dera Ghazi Khan divisions.'),
(2210, 97, '_why_badge_text', 'field_home_why_badge_text'),
(2211, 97, 'why_heading', 'Why South Punjab, <span class=\"text-accent\">Why Now?</span>'),
(2212, 97, '_why_heading', 'field_home_why_heading'),
(2213, 97, 'why_text_1', 'Families across Multan, Bahawalpur and Dera Ghazi Khan divisions, want quality college education close to home and are willing to pay for it. Yet many towns still lack a trusted name to turn to. A UGC campus meets that demand, earns tuition income over time and creates an enduring legacy in your community.\r\n'),
(2214, 97, '_why_text_1', 'field_home_why_text_1'),
(2215, 97, 'why_text_2', 'Partnering now means joining an established brand while the network is still young and securing your city before someone else does.\r\n'),
(2216, 97, '_why_text_2', 'field_home_why_text_2'),
(2217, 97, 'why_highlight_title', 'First-Mover Advantage'),
(2218, 97, '_why_highlight_title', 'field_home_why_highlight_title'),
(2219, 97, 'why_highlight_text', 'Secure your territory in high-demand regions before the market saturates.'),
