(2365, 97, 'models_card_3_is_highlighted', '0'),
(2366, 97, '_models_card_3_is_highlighted', 'field_home_models_card3_highlight'),
(2367, 97, 'models_card_3', ''),
(2368, 97, '_models_card_3', 'field_home_models_card3'),
(2369, 97, 'opportunity_item_1_text', 'Entrepreneurs and business owners seeking a respectable, long-term venture.'),
(2370, 97, '_opportunity_item_1_text', 'field_home_opportunity_item1'),
(2371, 97, 'opportunity_item_2_text', 'Property owners with suitable land or commercial buildings in South Punjab.'),
(2372, 97, '_opportunity_item_2_text', 'field_home_opportunity_item2'),
(2373, 97, 'opportunity_item_3_text', 'Owners of existing schools, colleges or academies looking to grow under a stronger brand.'),
(2374, 97, '_opportunity_item_3_text', 'field_home_opportunity_item3'),
(2375, 97, 'opportunity_item_4_text', 'Retired professionals seeking to invest in a meaningful community focused enterprise.'),
(2376, 97, '_opportunity_item_4_text', 'field_home_opportunity_item4'),
(2377, 98, '_edit_lock', '1786110514:1'),
(2378, 98, '_wp_page_template', 'page-templates/template-about.php'),
(2379, 98, '_edit_last', '1'),
(2380, 98, 'hero_image', '100'),
(2381, 98, '_hero_image', 'field_about_hero_image'),
(2382, 98, 'hero_title', 'About UGC'),
(2383, 98, '_hero_title', 'field_about_hero_title'),
(2384, 98, 'trust_image', '108'),
(2385, 98, '_trust_image', 'field_about_trust_image'),
(2386, 98, 'trust_heading', 'A New Way to Build a <span class=\"text-accent\">College</span>, <span class=\"text-accent\">Backed by a Name</span> That Has <span class=\"text-accent\">Earned Trust</span>'),
(2387, 98, '_trust_heading', 'field_about_trust_heading'),
(2388, 98, 'trust_text', 'United Group of Colleges (UGC) is a franchise network designed to bring quality, well-managed college education to towns and cities across South Punjab. By combining private investment with academic governance, we provide investors with a credible and well-supported pathway to establish sustainable higher education institutions in their home communities.\r\n'),
(2389, 98, '_trust_text', 'field_about_trust_text'),
(2390, 98, 'trust_list_title', 'What \"Backed by UGF\" Means: UGC operates with academic guidance and governance support inspired by the University of Southern Punjab (USP), an HEC-chartered private university in Multan recognized for its academic excellence and high standards across the region.'),
(2391, 98, '_trust_list_title', 'field_about_trust_list_title'),
(2392, 98, 'trust_item_1_label', 'Independent Entity'),
(2393, 98, '_trust_item_1_label', 'field_about_trust_item1_label'),
(2394, 98, 'trust_item_1_text', 'UGC is an independent corporate franchise network.\r\n'),
(2395, 98, '_trust_item_1_text', 'field_about_trust_item1_text'),
(2396, 98, 'trust_item_1', ''),
(2397, 98, '_trust_item_1', 'field_about_trust_item1'),
(2398, 98, 'trust_item_2_label', 'Governance Framework'),
(2399, 98, '_trust_item_2_label', 'field_about_trust_item2_label'),
(2400, 98, 'trust_item_2_text', 'Institutional policies, academic practices and quality assurance standards are developed using USP\'s academic expertise and governance framework.\r\n'),
(2401, 98, '_trust_item_2_text', 'field_about_trust_item2_text'),
(2402, 98, 'trust_item_2', ''),
(2403, 98, '_trust_item_2', 'field_about_trust_item2'),
(2404, 98, 'trust_item_3_label', 'Qualifications & Affiliations'),
(2405, 98, '_trust_item_3_label', 'field_about_trust_item3_label'),
(2406, 98, 'trust_item_3_text', 'UGC does not award USP qualifications or offer USP\'s internal degree programmes. Academic qualifications are awarded through proposed affiliations with local education boards (Intermediate) and regional public-sector universities (Degree and Professional Programmes), subject to all required regulatory and government approvals.\r\n'),
(2407, 98, '_trust_item_3_text', 'field_about_trust_item3_text'),
(2408, 98, 'trust_item_3', ''),
(2409, 98, '_trust_item_3', 'field_about_trust_item3'),
(2410, 98, 'model_image', '110'),
(2411, 98, '_model_image', 'field_about_model_image'),
(2412, 98, 'model_heading', 'Why We Built the <span class=\"text-accent\">UGC Franchise Model</span>'),
(2413, 98, '_model_heading', 'field_about_model_heading'),
(2414, 98, 'model_content', '<span style=\"font-weight: 400;\">Quality education should not be limited to major cities. </span><b>However, establishing a college from the ground up is often time-consuming, complex and capital-intensive.</b>\r\n\r\n<span style=\"font-weight: 400;\">To simplify the process, we have packaged everything an investor needs—including the brand, curriculum framework, digital management systems, staff training and operational support—into a comprehensive, </span><b>turnkey franchise model</b><span style=\"font-weight: 400;\">.</span>\r\n\r\n<span style=\"font-weight: 400;\">You provide the investment and campus; we provide the institutional framework. Together, we enable the establishment of high-quality colleges </span><b>more efficiently and effectively than either party could achieve independently.</b>'),
(2415, 98, '_model_content', 'field_about_model_content');
INSERT INTO `wp_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(2416, 98, 'pillars_heading', 'Core Pillars of the <span class=\"text-accent\">UGC Model</span>'),
(2417, 98, '_pillars_heading', 'field_about_pillars_heading'),
(2418, 98, 'pillar_1_icon', '129'),
(2419, 98, '_pillar_1_icon', 'field_about_pillar1_icon'),
(2420, 98, 'pillar_1_title', 'Academic Excellence'),
(2421, 98, '_pillar_1_title', 'field_about_pillar1_title'),
(2422, 98, 'pillar_1_text', 'Bridging educational gaps across the region by combining modern academic standards with structured pathways toward regulatory compliance and institutional quality.\r\n'),
(2423, 98, '_pillar_1_text', 'field_about_pillar1_text'),
(2424, 98, 'pillar_1', ''),
(2425, 98, '_pillar_1', 'field_about_pillar1'),
(2426, 98, 'pillar_2_icon', '130'),
(2427, 98, '_pillar_2_icon', 'field_about_pillar2_icon'),
(2428, 98, 'pillar_2_title', 'Turnkey Educational Enterprise'),
(2429, 98, '_pillar_2_title', 'field_about_pillar2_title'),
(2430, 98, 'pillar_2_text', 'Reducing execution risk for investors through comprehensive operational manuals, digital campus management systems, standardized processes and continuous staff development.\r\n'),
(2431, 98, '_pillar_2_text', 'field_about_pillar2_text'),
(2432, 98, 'pillar_2', ''),
(2433, 98, '_pillar_2', 'field_about_pillar2'),
(2434, 98, 'pillar_3_icon', '131'),
(2435, 98, '_pillar_3_icon', 'field_about_pillar3_icon'),
(2436, 98, 'pillar_3_title', 'Creating Lasting Impact and Sustainable Growth'),
(2437, 98, '_pillar_3_title', 'field_about_pillar3_title'),
(2438, 98, 'pillar_3_text', 'Transforming commercial assets into thriving educational institutions that generate long-term financial returns while creating a meaningful legacy for families and communities.\r\n'),
(2439, 98, '_pillar_3_text', 'field_about_pillar3_text'),
(2440, 98, 'pillar_3', ''),
(2441, 98, '_pillar_3', 'field_about_pillar3'),
(2442, 98, 'quality_image', '112'),
(2443, 98, '_quality_image', 'field_about_quality_image'),
(2444, 98, 'quality_heading', 'High Standards of <span class=\"text-accent\">Quality Assurance</span>'),
(2445, 98, '_quality_heading', 'field_about_quality_heading'),
(2446, 98, 'quality_text', 'Every UGC franchise operates under consistent network-wide quality standards to safeguard both the brand\'s reputation and our partners\' investments.\r\n'),
(2447, 98, '_quality_text', 'field_about_quality_text'),
(2448, 98, 'quality_item_1_label', 'Standardized Curriculum'),
(2449, 98, '_quality_item_1_label', 'field_about_quality_item1_label'),
(2450, 98, 'quality_item_1_text', 'A unified academic framework implemented across all campuses.\r\n'),
(2451, 98, '_quality_item_1_text', 'field_about_quality_item1_text'),
(2452, 98, 'quality_item_1', ''),
(2453, 98, '_quality_item_1', 'field_about_quality_item1'),
(2454, 98, 'quality_item_2_label', 'Central Operations Playbook'),
(2455, 98, '_quality_item_2_label', 'field_about_quality_item2_label'),
(2456, 98, 'quality_item_2_text', 'Standardized administrative and operational procedures to ensure consistency and efficiency.\r\n'),
(2457, 98, '_quality_item_2_text', 'field_about_quality_item2_text'),
(2458, 98, 'quality_item_2', ''),
(2459, 98, '_quality_item_2', 'field_about_quality_item2'),
(2460, 98, 'quality_item_3_label', 'Digital Campus Infrastructure'),
(2461, 98, '_quality_item_3_label', 'field_about_quality_item3_label'),
(2462, 98, 'quality_item_3_text', 'Integrated digital platforms for campus management, student records and operational monitoring.\r\n'),
(2463, 98, '_quality_item_3_text', 'field_about_quality_item3_text'),
(2464, 98, 'quality_item_3', ''),
(2465, 98, '_quality_item_3', 'field_about_quality_item3'),
(2466, 98, 'quality_item_4_label', 'Staff Development'),
(2467, 98, '_quality_item_4_label', 'field_about_quality_item4_label'),
(2468, 98, 'quality_item_4_text', 'Ongoing recruitment support, professional development and teacher training programmes.'),
(2469, 98, '_quality_item_4_text', 'field_about_quality_item4_text'),
(2470, 98, 'quality_item_4', ''),
(2471, 98, '_quality_item_4', 'field_about_quality_item4'),
(2472, 98, 'quality_item_5_label', 'Quality Reviews'),
(2473, 98, '_quality_item_5_label', 'field_about_quality_item5_label'),
(2474, 98, 'quality_item_5_text', 'Regular academic evaluations, operational audits and continuous quality improvement.\r\n'),
(2475, 98, '_quality_item_5_text', 'field_about_quality_item5_text'),
(2476, 98, 'quality_item_5', ''),
(2477, 98, '_quality_item_5', 'field_about_quality_item5'),
(2478, 98, 'cta_heading', 'Our Focus South Punjab and Beyond'),
(2479, 98, '_cta_heading', 'field_about_cta_heading'),
(2480, 98, 'cta_text', 'UGC is initially focused on  Multan, Bahawalpur and Dera Ghazi Khan divisions and surrounding towns, where demand for trusted higher education is outpacing supply. Over time, UGC plans to expand the network across Pakistan, allowing early partners to grow alongside an expanding national brand.\r\n'),
(2481, 98, '_cta_text', 'field_about_cta_text'),
(2482, 99, 'hero_image', ''),
