(2831, 105, 'trust_item_3_label', 'Qualifications & Affiliations'),
(2832, 105, '_trust_item_3_label', 'field_about_trust_item3_label'),
(2833, 105, 'trust_item_3_text', 'UGC does not award USP qualifications or offer USP\'s internal degree programmes. Academic qualifications are awarded through proposed affiliations with local education boards (Intermediate) and regional public-sector universities (Degree and Professional Programmes), subject to all required regulatory and government approvals.\r\n'),
(2834, 105, '_trust_item_3_text', 'field_about_trust_item3_text'),
(2835, 105, 'trust_item_3', ''),
