(3025, 111, 'footnotes', ''),
(3027, 111, 'hero_image', '100'),
(3028, 111, '_hero_image', 'field_about_hero_image'),
(3029, 111, 'hero_title', 'About UGC'),
(3030, 111, '_hero_title', 'field_about_hero_title'),
(3031, 111, 'trust_image', '108'),
(3032, 111, '_trust_image', 'field_about_trust_image'),
(3033, 111, 'trust_heading', 'A New Way to Build a <span class=\"text-accent\">College</span>, <span class=\"text-accent\">Backed by a Name</span> That Has <span class=\"text-accent\">Earned Trust</span>'),
(3034, 111, '_trust_heading', 'field_about_trust_heading'),
(3035, 111, 'trust_text', 'United Group of Colleges (UGC) is a franchise network designed to bring quality, well-managed college education to towns and cities across South Punjab. By combining private investment with academic governance, we provide investors with a credible and well-supported pathway to establish sustainable higher education institutions in their home communities.\r\n'),
(3036, 111, '_trust_text', 'field_about_trust_text'),
(3037, 111, 'trust_list_title', 'What \"Backed by UGF\" Means: UGC operates with academic guidance and governance support inspired by the University of Southern Punjab (USP), an HEC-chartered private university in Multan recognized for its academic excellence and high standards across the region.'),
(3038, 111, '_trust_list_title', 'field_about_trust_list_title'),
(3039, 111, 'trust_item_1_label', 'Independent Entity'),
(3040, 111, '_trust_item_1_label', 'field_about_trust_item1_label'),
(3041, 111, 'trust_item_1_text', 'UGC is an independent corporate franchise network.\r\n'),
(3042, 111, '_trust_item_1_text', 'field_about_trust_item1_text'),
(3043, 111, 'trust_item_1', ''),
(3044, 111, '_trust_item_1', 'field_about_trust_item1'),
(3045, 111, 'trust_item_2_label', 'Governance Framework'),
(3046, 111, '_trust_item_2_label', 'field_about_trust_item2_label'),
(3047, 111, 'trust_item_2_text', 'Institutional policies, academic practices and quality assurance standards are developed using USP\'s academic expertise and governance framework.\r\n'),
(3048, 111, '_trust_item_2_text', 'field_about_trust_item2_text'),
(3049, 111, 'trust_item_2', ''),
(3050, 111, '_trust_item_2', 'field_about_trust_item2'),
(3051, 111, 'trust_item_3_label', 'Qualifications & Affiliations'),
(3052, 111, '_trust_item_3_label', 'field_about_trust_item3_label'),
(3053, 111, 'trust_item_3_text', 'UGC does not award USP qualifications or offer USP\'s internal degree programmes. Academic qualifications are awarded through proposed affiliations with local education boards (Intermediate) and regional public-sector universities (Degree and Professional Programmes), subject to all required regulatory and government approvals.\r\n'),
(3054, 111, '_trust_item_3_text', 'field_about_trust_item3_text'),
(3055, 111, 'trust_item_3', ''),
(3056, 111, '_trust_item_3', 'field_about_trust_item3'),
(3057, 111, 'model_image', '110'),
(3058, 111, '_model_image', 'field_about_model_image'),
(3059, 111, 'model_heading', 'Why We Built the <span class=\"text-accent\">UGC Franchise Model</span>'),
(3060, 111, '_model_heading', 'field_about_model_heading'),
(3061, 111, 'model_content', '<span style=\"font-weight: 400;\">Quality education should not be limited to major cities. </span><b>However, establishing a college from the ground up is often time-consuming, complex and capital-intensive.</b>\r\n\r\n<span style=\"font-weight: 400;\">To simplify the process, we have packaged everything an investor needs—including the brand, curriculum framework, digital management systems, staff training and operational support—into a comprehensive, </span><b>turnkey franchise model</b><span style=\"font-weight: 400;\">.</span>\r\n\r\n<span style=\"font-weight: 400;\">You provide the investment and campus; we provide the institutional framework. Together, we enable the establishment of high-quality colleges </span><b>more efficiently and effectively than either party could achieve independently.</b>'),
(3062, 111, '_model_content', 'field_about_model_content'),
(3063, 111, 'pillars_heading', 'Core Pillars of the <span class=\"text-accent\">UGC Model</span>'),
(3064, 111, '_pillars_heading', 'field_about_pillars_heading'),
(3065, 111, 'pillar_1_icon', ''),
(3066, 111, '_pillar_1_icon', 'field_about_pillar1_icon'),
(3067, 111, 'pillar_1_title', 'Academic Excellence'),
(3068, 111, '_pillar_1_title', 'field_about_pillar1_title'),
(3069, 111, 'pillar_1_text', 'Bridging educational gaps across the region by combining modern academic standards with structured pathways toward regulatory compliance and institutional quality.\r\n'),
(3070, 111, '_pillar_1_text', 'field_about_pillar1_text'),
(3071, 111, 'pillar_1', ''),
(3072, 111, '_pillar_1', 'field_about_pillar1'),
