(3075, 111, 'pillar_2_title', 'Turnkey Educational Enterprise'),
(3076, 111, '_pillar_2_title', 'field_about_pillar2_title'),
(3077, 111, 'pillar_2_text', 'Reducing execution risk for investors through comprehensive operational manuals, digital campus management systems, standardized processes and continuous staff development.\r\n'),
(3078, 111, '_pillar_2_text', 'field_about_pillar2_text'),
