(3875, 128, 'hero_image', '21'),
(3876, 128, '_hero_image', 'field_home_hero_image'),
(3877, 128, 'hero_title', 'Open a College. Partner With a Name People Already Trust.'),
(3878, 128, '_hero_title', 'field_home_hero_title'),
(3879, 128, 'hero_text', 'United Group of Colleges (UGC) enables visionaries, landowners and educational leaders to establish and operate a high-impact college in South Punjab under an established academic brand, without building an institution from scratch. We help you transform your existing campus into a modern, fully managed institution: you supply the property and capital, while we provide the brand, digital management systems, operational playbooks, staff training and continuous academic oversight. '),
(3880, 128, '_hero_text', 'field_home_hero_text'),
(3881, 128, 'hero_button_1_text', 'Request Franchise Information'),
(3882, 128, '_hero_button_1_text', 'field_home_hero_btn1_text'),
(3883, 128, 'hero_button_1_url', ''),
(3884, 128, '_hero_button_1_url', 'field_home_hero_btn1_url'),
(3885, 128, 'hero_button_2_text', 'See How It Works'),
(3886, 128, '_hero_button_2_text', 'field_home_hero_btn2_text'),
