(4085, 132, 'hero_image', '100'),
(4086, 132, '_hero_image', 'field_about_hero_image'),
(4087, 132, 'hero_title', 'About UGC'),
(4088, 132, '_hero_title', 'field_about_hero_title'),
(4089, 132, 'trust_image', '108'),
(4090, 132, '_trust_image', 'field_about_trust_image'),
(4091, 132, 'trust_heading', 'A New Way to Build a <span class=\"text-accent\">College</span>, <span class=\"text-accent\">Backed by a Name</span> That Has <span class=\"text-accent\">Earned Trust</span>'),
(4092, 132, '_trust_heading', 'field_about_trust_heading'),
(4093, 132, 'trust_text', 'United Group of Colleges (UGC) is a franchise network designed to bring quality, well-managed college education to towns and cities across South Punjab. By combining private investment with academic governance, we provide investors with a credible and well-supported pathway to establish sustainable higher education institutions in their home communities.\r\n'),
(4094, 132, '_trust_text', 'field_about_trust_text'),
(4095, 132, 'trust_list_title', 'What \"Backed by UGF\" Means: UGC operates with academic guidance and governance support inspired by the University of Southern Punjab (USP), an HEC-chartered private university in Multan recognized for its academic excellence and high standards across the region.'),
(4096, 132, '_trust_list_title', 'field_about_trust_list_title'),
(4097, 132, 'trust_item_1_label', 'Independent Entity'),
(4098, 132, '_trust_item_1_label', 'field_about_trust_item1_label'),
(4099, 132, 'trust_item_1_text', 'UGC is an independent corporate franchise network.\r\n'),
(4100, 132, '_trust_item_1_text', 'field_about_trust_item1_text'),
(4101, 132, 'trust_item_1', ''),
(4102, 132, '_trust_item_1', 'field_about_trust_item1'),
(4103, 132, 'trust_item_2_label', 'Governance Framework'),
(4104, 132, '_trust_item_2_label', 'field_about_trust_item2_label'),
(4105, 132, 'trust_item_2_text', 'Institutional policies, academic practices and quality assurance standards are developed using USP\'s academic expertise and governance framework.\r\n'),
(4106, 132, '_trust_item_2_text', 'field_about_trust_item2_text'),
(4107, 132, 'trust_item_2', ''),
(4108, 132, '_trust_item_2', 'field_about_trust_item2'),
(4109, 132, 'trust_item_3_label', 'Qualifications & Affiliations'),
(4110, 132, '_trust_item_3_label', 'field_about_trust_item3_label'),
(4111, 132, 'trust_item_3_text', 'UGC does not award USP qualifications or offer USP\'s internal degree programmes. Academic qualifications are awarded through proposed affiliations with local education boards (Intermediate) and regional public-sector universities (Degree and Professional Programmes), subject to all required regulatory and government approvals.\r\n'),
(4112, 132, '_trust_item_3_text', 'field_about_trust_item3_text'),
(4113, 132, 'trust_item_3', ''),
(4114, 132, '_trust_item_3', 'field_about_trust_item3'),
(4115, 132, 'model_image', '110'),
(4116, 132, '_model_image', 'field_about_model_image'),
(4117, 132, 'model_heading', 'Why We Built the <span class=\"text-accent\">UGC Franchise Model</span>'),
(4118, 132, '_model_heading', 'field_about_model_heading'),
(4119, 132, 'model_content', '<span style=\"font-weight: 400;\">Quality education should not be limited to major cities. </span><b>However, establishing a college from the ground up is often time-consuming, complex and capital-intensive.</b>\r\n\r\n<span style=\"font-weight: 400;\">To simplify the process, we have packaged everything an investor needs—including the brand, curriculum framework, digital management systems, staff training and operational support—into a comprehensive, </span><b>turnkey franchise model</b><span style=\"font-weight: 400;\">.</span>\r\n\r\n<span style=\"font-weight: 400;\">You provide the investment and campus; we provide the institutional framework. Together, we enable the establishment of high-quality colleges </span><b>more efficiently and effectively than either party could achieve independently.</b>'),
(4120, 132, '_model_content', 'field_about_model_content'),
(4121, 132, 'pillars_heading', 'Core Pillars of the <span class=\"text-accent\">UGC Model</span>'),
(4122, 132, '_pillars_heading', 'field_about_pillars_heading'),
(4123, 132, 'pillar_1_icon', '129'),
(4124, 132, '_pillar_1_icon', 'field_about_pillar1_icon'),
(4125, 132, 'pillar_1_title', 'Academic Excellence'),
(4126, 132, '_pillar_1_title', 'field_about_pillar1_title'),
(4127, 132, 'pillar_1_text', 'Bridging educational gaps across the region by combining modern academic standards with structured pathways toward regulatory compliance and institutional quality.\r\n'),
(4128, 132, '_pillar_1_text', 'field_about_pillar1_text'),
(4129, 132, 'pillar_1', ''),
(4130, 132, '_pillar_1', 'field_about_pillar1'),
(4131, 132, 'pillar_2_icon', '130'),
(4132, 132, '_pillar_2_icon', 'field_about_pillar2_icon'),
(4133, 132, 'pillar_2_title', 'Turnkey Educational Enterprise'),
(4134, 132, '_pillar_2_title', 'field_about_pillar2_title'),
(4135, 132, 'pillar_2_text', 'Reducing execution risk for investors through comprehensive operational manuals, digital campus management systems, standardized processes and continuous staff development.\r\n'),
(4136, 132, '_pillar_2_text', 'field_about_pillar2_text'),
(4137, 132, 'pillar_2', ''),
(4138, 132, '_pillar_2', 'field_about_pillar2'),
