(4141, 132, 'pillar_3_title', 'Creating Lasting Impact and Sustainable Growth'),
(4142, 132, '_pillar_3_title', 'field_about_pillar3_title'),
(4143, 132, 'pillar_3_text', 'Transforming commercial assets into thriving educational institutions that generate long-term financial returns while creating a meaningful legacy for families and communities.\r\n'),
(4144, 132, '_pillar_3_text', 'field_about_pillar3_text'),
(4145, 132, 'pillar_3', ''),
(4146, 132, '_pillar_3', 'field_about_pillar3'),
